 */
public static function unwrapResult($value)
{
    if (is_string($value)) {
        if ((isset($value[0])) && ($value[0] == self::FORMULA_STRING_QUOTE) && (substr($value, -1) == self::FORMULA_STRING_QUOTE)) {
